import json

with open('/app/resources/treasury_bulletin_1942_07.json', 'r') as f:
    data = json.load(f)

# Look for tables with "net" in them or tables with the right structure
def find_tables(d, path=""):
    if isinstance(d, dict):
        for k, v in d.items():
            if 'table' in k.lower() or 'net' in str(k).lower():
                print(f"Key: {path}.{k}")
            find_tables(v, f"{path}.{k}")
    elif isinstance(d, list) and len(d) > 0:
        find_tables(d[0], f"{path}[0]")

# Just look for "receipt" related keys
def find_receipts(d, path=""):
    if isinstance(d, dict):
        for k, v in d.items():
            if 'receipt' in k.lower() and 'table' in str(v).lower()[:100]:
                print(f"Found receipts table at {path}.{k}")
            find_receipts(v, f"{path}.{k}")
    elif isinstance(d, list):
        for i, item in enumerate(d):
            find_receipts(item, f"{path}[{i}]")

find_receipts(data)
